PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS players (id TEXT PRIMARY KEY, username TEXT NOT NULL COLLATE NOCASE UNIQUE, email TEXT NOT NULL COLLATE NOCASE UNIQUE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS consoles (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS games (id TEXT PRIMARY KEY, console_id TEXT NOT NULL REFERENCES consoles(id), title TEXT NOT NULL, published INTEGER NOT NULL DEFAULT 0 CHECK(published IN (0,1)));
CREATE TABLE IF NOT EXISTS achievements (id TEXT PRIMARY KEY, game_id TEXT NOT NULL REFERENCES games(id), title TEXT NOT NULL, description TEXT NOT NULL, points INTEGER NOT NULL CHECK(points > 0), published INTEGER NOT NULL DEFAULT 0 CHECK(published IN (0,1)));
CREATE TABLE IF NOT EXISTS unlocks (player_id TEXT NOT NULL REFERENCES players(id), achievement_id TEXT NOT NULL REFERENCES achievements(id), unlocked_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(player_id,achievement_id));
INSERT OR IGNORE INTO consoles(id,name) VALUES ('nds','Nintendo DS');